mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value orig;
  struct mrb_io *io;
  struct mrb_io *orig_io;

  orig = mrb_get_args(mrb, "o", &orig);
  if (!mrb_io_p(orig)) {
    mrb_raise(mrb, E_TYPE_ERROR, "wrong argument type");
  }

  mrb_check_type(copy, MRB_TT_OBJECT);
  if (mrb_obj_equal(mrb, copy, orig)) {
    return copy;
  }

  orig_io = DATA_PTR(orig);
  io = (struct mrb_io *)mrb_malloc(mrb, sizeof(*io));
  if (!io) {
    mrb_raise(mrb, E_NO_MEMORY_ERROR, "failed to allocate IO");
  }

  *io = *orig_io;

  if (io->io) {
    if (io->mode & MRB_IO_READABLE) {
      if (io->mode & MRB_IO_WRITABLE) {
        io->f = fdopen(dup2(fileno(io->io->f), mrb_get_io_fileno(mrb, copy)), "a+");
      }
      else {
        io->f = fdopen(dup2(fileno(io->io->f), mrb_get_io_fileno(mrb, copy)), "r");
      }
    }
    else {
      io->f = fdopen(dup2(fileno(io->io->f), mrb_get_io_fileno(mrb, copy)), "w");
    }

    if (!io->f) {
      mrb_free(mrb, io);
      mrb_sys_fail(mrb, "failed to duplicate file descriptor");
    }
  }

  DATA_PTR(copy) = io;
  DATA_TYPE(copy) = &mrb_io_type;

  mrb_iv_set(mrb, mrb_obj_value(copy), mrb_intern_lit(mrb, "path"), mrb_iv_get(mrb, orig, mrb_intern_lit(mrb, "path")));
  mrb_iv_set(mrb, mrb_obj_value(copy), mrb_intern_lit(mrb, "binmode"), mrb_iv_get(mrb, orig, mrb_intern_lit(mrb, "binmode")));

  return copy;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value orig;
  struct mrb_io *io;
  int fd;

  orig = mrb_get_args(mrb, "o", &copy);
  if (mrb_obj_equal(mrb, copy, orig)) {
    return copy;
  }

  mrb_gc_unregister(mrb, mrb Object copy);
  mrb_data_init(mrb, copy, 0, 0);

  io = (struct mrb_io *)mrb_malloc(mrb, sizeof(*io));
  io->fd = -1;
  io->mode = 0;
  io->path = 0;
  io->sync = 0;
  io->binmode = 0;
  io->lineno = 0;
  io->readable = 0;
  io->writable = 0;
  io->eof = 0;

  fd = mrb_io_fileno(mrb, orig);
  if (fd == -1) {
    mrb_raise(mrb, E_IO_ERROR, "original IO object has no file descriptor");
  }

  io->fd = dup(fd);
  if (io->fd == -1) {
    mrb_sys_fail(mrb, "dup");
  }

  io->readable = mrb_io_readabp(mrb, orig);
  io->writable = mrb_io_writeabp(mrb, orig);
  io->sync = mrb_io_syncp(mrb, orig);
  mrb_data_init(copy, io, &mrb_io_type);

  return copy;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value original;
  mrb_io *io, *orig_io;
  int flags;

  original = mrb_get_args(mrb, "o", &copy);
  if (mrb_obj_equal(mrb, copy, original)) {
    return copy;
  }

  mrb_data_initialize(mrb, copy, NULL, NULL);

  if (mrb_type(original) != MRB_TT_DATA) {
    mrb_raise(mrb, E_TYPE_ERROR, "IO required");
  }

  orig_io = (mrb_io *)DATA_PTR(original);
  if (orig_io == NULL) {
    mrb_raise(mrb, E_RUNTIME_ERROR, "original IO is invalid");
  }

  flags = fcntl(orig_io->fd, F_GETFL);
  if (flags == -1) {
    mrb_sys_fail(mrb, "fcntl(F_GETFL)");
  }

  io = (mrb_io *)mrb_malloc(mrb, sizeof(mrb_io));
  io->fd = dup(orig_io->fd);
  if (io->fd == -1) {
    mrb_free(mrb, io);
    mrb_sys_fail(mrb, "dup");
  }

  if (fcntl(io->fd, F_SETFD, flags) == -1) {
    close(io->fd);
    mrb_free(mrb, io);
    mrb_sys_fail(mrb, "fcntl(F_SETFD)");
  }

  io->readable = orig_io->readable;
  io->writable = orig_io->writable;
  io->sync = orig_io->sync;
  io->mode = orig_io->mode;
  io->path = orig_io->path ? mrb_str_dup(mrb, orig_io->path) : mrb_nil_value();

  mrb_data_assign(mrb, copy, io, &mrb_io_type);
  return copy;
}

