mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value orig;
  struct mrb_io *io, *orig_io;

  orig = mrb_get_args(mrb, "o", &orig);
  if (mrb_obj_equal(mrb, copy, orig)) return copy;

  mrb_check_type(mrb, orig, MRB_TT_IO);
  io = (struct mrb_io *)mrb_get_ptr(copy);
  orig_io = (struct mrb_io *)mrb_get_ptr(orig);

  if (io->io) {
    mrb_io_close(mrb, copy);
  }

  io->io = g_mapped_file_dup(orig_io->io);
  if (!io->io) {
    mrb_raise(mrb, E_SYSTEMCALL_ERROR, "dup");
  }

  io->readable = orig_io->readable;
  io->writable = orig_io->writable;
  io->sync = orig_io->sync;

  return copy;
}

mrb_value
mrb_io_init_copy(mrb_state *mrb, mrb_value copy)
{
  mrb_value orig;
  struct mrb_io *io;
  int fd;

  orig = mrb_get_args(mrb, "o", &copy);
  io = mrb_io_ptr(copy);
  if (io->fd != -1) {
    mrb_gc_unregister(mrb, copy);
    close(io->fd);
    io->fd = -1;
  }
  fd = dup(mrb_io_ptr(orig)->fd);
  if (fd == -1) {
    mrb_sys_fail(mrb, "duplicate file descriptor");
  }
  io->fd = fd;
  io->readable = mrb_io_ptr(orig)->readable;
  io->writable = mrb_io_ptr(orig)->writable;
  io->sync = mrb_io_ptr(orig)->sync;
  mrb_gc_register(mrb, copy);
  return copy;
}
